# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEDİNE\'DE TOPLUMUN DİĞER KESİMLERİ VE MEDİNE VESİKASI</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Medine Vesikası İlkeleri</text>\n  <text x="40" y="103" font-size="10.5" fill="#334155">• Din ve vicdan hürriyeti güvencesi</text>\n  <text x="40" y="125" font-size="10.5" fill="#334155">• Dış saldırılara karşı Medine\'yi</text>\n  <text x="48" y="142" font-size="10.5" fill="#475569">birlikte savunma yükümlülüğü</text>\n  <text x="40" y="164" font-size="10.5" fill="#334155">• Düşmanla gizli ittifak yasağı</text>\n  <text x="40" y="186" font-size="10.5" fill="#334155">• Anlaşmazlıklarda son yargı</text>\n  <text x="48" y="203" font-size="10.5" font-weight="bold" fill="#1e40af">mercii: Hz. Muhammed (s.a.v.)</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Üç Yahudi Kabîlesi</text>\n  <text x="262" y="102" font-size="10.5" font-weight="bold" fill="#991b1b">1. Benî Kaynukā\' (624):</text>\n  <text x="270" y="118" font-size="10" fill="#475569">Çarşıda Müslüman kadına saldırı ve</text>\n  <text x="270" y="132" font-size="10" fill="#475569">isyan (Bedir sonrası sürgün).</text>\n  <text x="262" y="154" font-size="10.5" font-weight="bold" fill="#991b1b">2. Benî Nadîr (625):</text>\n  <text x="270" y="170" font-size="10" fill="#475569">Hz. Peygamber\'e suikast girişimi.</text>\n  <text x="262" y="192" font-size="10.5" font-weight="bold" fill="#991b1b">3. Benî Kurayza (627):</text>\n  <text x="270" y="208" font-size="10" fill="#475569">Hendek Savaşı\'nda düşmanla iş birliği.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Münafıklar ve Çevre Kabîleler</text>\n  <text x="485" y="103" font-size="10.5" fill="#334155">• Münafıklar (İbn Übey): Uhud\'da</text>\n  <text x="493" y="120" font-size="10" fill="#475569">orduyu terk, İfk Hadisesi, Dırâr</text>\n  <text x="493" y="135" font-size="10" fill="#475569">Mescidi (zahire göre muamele).</text>\n  <text x="485" y="160" font-size="10.5" fill="#334155">• Çevre Kabîleler: Saldırmazlık</text>\n  <text x="493" y="177" font-size="10" fill="#475569">antlaşmaları, elçiler (Senetü\'l-vüfûd)</text>\n  <text x="493" y="193" font-size="10" fill="#475569">ve İslam öğretmenleri gönderimi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEDİNE\'DEKİ YAHUDİ KABÎLELERİYLE İLİŞKİLERİN SEYRİ</text>\n  <rect x="30" y="55" width="195" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Benî Kaynukā\' (H. 2 / 624)</text>\n  <text x="42" y="105" font-size="10.5" fill="#334155">• Kuyumculuk ve ticaretle</text>\n  <text x="42" y="121" font-size="10.5" fill="#334155">uğraşan kabîledir.</text>\n  <text x="42" y="143" font-size="10.5" fill="#334155">• Çarşılarında Müslüman bir</text>\n  <text x="42" y="159" font-size="10.5" fill="#334155">kadının örtüsüne yapılan</text>\n  <text x="42" y="175" font-size="10.5" fill="#334155">saygısızlık ve bir Müslümanın</text>\n  <text x="42" y="191" font-size="10.5" fill="#334155">şehit edilmesi üzerine</text>\n  <text x="42" y="207" font-size="10.5" font-weight="bold" fill="#1e40af">Medine\'den çıkarıldılar.</text>\n  <rect x="252" y="55" width="195" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2. Benî Nadîr (H. 4 / 625)</text>\n  <text x="264" y="105" font-size="10.5" fill="#334155">• Diyet istişaresi için yurtlarına</text>\n  <text x="264" y="121" font-size="10.5" fill="#334155">gelen Hz. Peygamber\'in</text>\n  <text x="264" y="137" font-size="10.5" fill="#334155">üzerine damdan değirmen</text>\n  <text x="264" y="153" font-size="10.5" fill="#334155">taşı atarak suikast</text>\n  <text x="264" y="169" font-size="10.5" fill="#334155">düzenlemeye kalkıştılar.</text>\n  <text x="264" y="191" font-size="10.5" font-weight="bold" fill="#854d0e">• Kuşatma sonrası Hayber ve</text>\n  <text x="264" y="207" font-size="10.5" font-weight="bold" fill="#854d0e">Şam tarafına göç ettiler.</text>\n  <rect x="475" y="55" width="195" height="175" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="572" y="80" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">3. Benî Kurayza (H. 5 / 627)</text>\n  <text x="487" y="105" font-size="10.5" fill="#334155">• Hendek Savaşı\'nın en kritik</text>\n  <text x="487" y="121" font-size="10.5" fill="#334155">anında Medine Vesikası\'nı</text>\n  <text x="487" y="137" font-size="10.5" fill="#334155">bozup müşrik ordusuyla</text>\n  <text x="487" y="153" font-size="10.5" fill="#334155">gizli ittifak kurdular.</text>\n  <text x="487" y="175" font-size="10.5" fill="#334155">• Kendi seçtikleri hakem</text>\n  <text x="487" y="191" font-size="10.5" font-weight="bold" fill="#991b1b">Sa\'d b. Muâz\'ın Tevrat\'a</text>\n  <text x="487" y="207" font-size="10.5" font-weight="bold" fill="#991b1b">uygun hükmüyle cezalandırıldılar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. PEYGAMBER\'İN MÜNAFIKLAR VE ÇEVRE KABÎLELER SİYASETİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Münafıklara Karşı Hikmetli Siyaset</text>\n  <text x="50" y="103" font-size="10.5" fill="#334155">• Zahire (dış görünüşe) göre muamele</text>\n  <text x="58" y="120" font-size="10" fill="#475569">ederek toplumsal iç savaşı önledi.</text>\n  <text x="50" y="142" font-size="10.5" fill="#334155">• İsimlerini (Huzeyfe b. Yemân dışında)</text>\n  <text x="58" y="159" font-size="10" fill="#475569">ifşa etmeyip tövbe kapısını açık tuttu.</text>\n  <text x="50" y="181" font-size="10.5" fill="#334155">• Ancak fitne merkezi olan Dırâr</text>\n  <text x="58" y="198" font-size="10" font-weight="bold" fill="#854d0e">Mescidi\'ni yıktırarak birliği korudu.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Çevre Kabîlelerle İlişkiler</text>\n  <text x="380" y="103" font-size="10.5" fill="#334155">• Güvenlik ve saldırmazlık antlaşmaları</text>\n  <text x="388" y="120" font-size="10" fill="#475569">(Cüheyne, Müzeyne, Gıfâr, Huzâa vb.)</text>\n  <text x="380" y="142" font-size="10.5" fill="#334155">• İslam\'ı öğretmek için muallimler gönderimi</text>\n  <text x="388" y="159" font-size="10" fill="#475569">(Recî\' ve Bi\'rimaûne şehitleri)</text>\n  <text x="380" y="181" font-size="10.5" fill="#334155">• Hicretin 9. yılı: Elçiler Yılı</text>\n  <text x="388" y="198" font-size="10" font-weight="bold" fill="#166534">(Senetü\'l-vüfûd) — Barışçıl katılım.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
